import{_ as t,o as r,c as i,ag as a}from"./chunks/framework.qXLDknWC.js";const u=JSON.parse('{"title":"Greetings Editor","description":"","frontmatter":{},"headers":[],"relativePath":"features/greetings-editor.md","filePath":"features/greetings-editor.md"}'),o={name:"features/greetings-editor.md"};function n(s,e,l,g,d,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="greetings-editor" tabindex="-1">Greetings Editor <a class="header-anchor" href="#greetings-editor" aria-label="Permalink to &quot;Greetings Editor&quot;">​</a></h1><p>The <strong>Greetings</strong> tab provides a dedicated two-panel editor for managing alternate greetings — the first messages your character sends during roleplay.</p><h2 id="two-panel-layout" tabindex="-1">Two-Panel Layout <a class="header-anchor" href="#two-panel-layout" aria-label="Permalink to &quot;Two-Panel Layout&quot;">​</a></h2><p>The greetings editor uses a sidebar + detail layout:</p><ul><li><strong>Left sidebar</strong> — Lists all greetings with content indicators and token counts.</li><li><strong>Right panel</strong> — Full CodeMirror editor with AI toolbar for the selected greeting.</li></ul><p>On mobile, the sidebar and detail panel switch between each other — tap a greeting to open it, tap <strong>Back to greetings</strong> to return to the list.</p><h2 id="greeting-list-sidebar" tabindex="-1">Greeting List Sidebar <a class="header-anchor" href="#greeting-list-sidebar" aria-label="Permalink to &quot;Greeting List Sidebar&quot;">​</a></h2><p>Each greeting card shows:</p><ul><li><strong>Content indicator</strong> — A green dot means the greeting has content; a grey dot means it&#39;s empty.</li><li><strong>Label</strong> — &quot;Greeting 1&quot;, &quot;Greeting 2&quot;, etc.</li><li><strong>Token count</strong> — Shown for the currently selected greeting.</li><li><strong>Delete button</strong> — Appears on hover. Removing a greeting requires confirmation.</li></ul><h3 id="adding-greetings" tabindex="-1">Adding Greetings <a class="header-anchor" href="#adding-greetings" aria-label="Permalink to &quot;Adding Greetings&quot;">​</a></h3><p>Click <strong>New Greeting</strong> at the bottom of the sidebar to add a blank greeting. The new greeting is automatically selected for editing.</p><h3 id="deleting-greetings" tabindex="-1">Deleting Greetings <a class="header-anchor" href="#deleting-greetings" aria-label="Permalink to &quot;Deleting Greetings&quot;">​</a></h3><p>Hover over a greeting card and click the trash icon. A confirmation dialog asks you to confirm before the greeting is removed. If you delete the currently selected greeting, selection moves to the previous one.</p><h2 id="greeting-editor" tabindex="-1">Greeting Editor <a class="header-anchor" href="#greeting-editor" aria-label="Permalink to &quot;Greeting Editor&quot;">​</a></h2><p>Selecting a greeting opens the full CodeMirror editor on the right. The editor includes all the same features as other text editors:</p><ul><li><strong>AI toolbar</strong> — Enhance, Rephrase, Custom, and polish operations. See <a href="/CharacterVault/docs/features/editor#ai-toolbar">Text Editor → AI Toolbar</a>.</li><li><strong>Search &amp; Replace</strong> — Press <code>Ctrl+F</code> or click the 🔍 button.</li><li><strong>Font size</strong> — Click <strong>aA</strong> to adjust.</li><li><strong>Auto-save</strong> — Changes are saved automatically with a short debounce (250ms after you stop typing).</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>First Message vs. Greetings</strong> — The <strong>First Message</strong> tab is the primary greeting. The Greetings tab holds alternate greetings that give players a choice of opening messages.</li><li><strong>Use the AI toolbar</strong> — Select a greeting and use Enhance or Custom to quickly rewrite or improve it.</li><li><strong>Keep greetings distinct</strong> — Each greeting should offer a noticeably different opening scenario or tone so players have meaningful choices.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/editor">Text Editor features</a></li><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a></li><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure AI provider</a></li></ul>',20)])])}const p=t(o,[["render",n]]);export{u as __pageData,p as default};
